# Test output as each cell's neighborhood Boolean expression across both masks with offsets and truth table.
for kind in ['L','R','xor','and','or','nand']:
 for dr in range(-3,4):
  for dc in range(-3,4):
   good=True
   for L,R,O in D:
    for r in range(4):
     for c in range(4):
      rr,cc=r+dr,c+dc
      a=L[rr][cc] if 0<=rr<4 and 0<=cc<4 else 0
      b=R[r][c]
